import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "zod";

// A server to check if a synthetic quote is valid based on a given amount.
const server = new McpServer({
  name: "codex-rg13-20261007-quote-checker",
  version: "1.0.0",
});

// Tool: check_synthetic_quote
server.tool(
  "check_synthetic_quote",
  "Checks if a synthetic quote is valid based on the provided amount.",
  {
    amount: z.number().describe("The amount of the synthetic quote"),
  },
  async (args) => {
    try {
      const isValid = args.amount >= 0 && args.amount <= 10000;
      return {
        content: [{ type: "text", text: JSON.stringify({ synthetic: true, valid: isValid }) }],
      };
    } catch (error) {
      return {
        content: [{ type: "text", text: `Error checking quote: ${error.message}` }],
      };
    }
  }
);

// Start the server
async function main() {
  const transport = new StdioServerTransport();
  await server.connect(transport);
  console.error("codex-rg13-20261007-quote-checker MCP server running on stdio");
}

main().catch(console.error);

